// IoT数据验证与转换示例
const deviceData = msg.payload;

// 基本数据验证
if (!deviceData.deviceId || !deviceData.timestamp || !deviceData.dataPoints) {
    msg.statusCode = 400;
    msg.payload = { error: '数据格式错误', message: '缺少必要字段' };
    return [null, msg]; // 发送到错误处理
}

// 数据转换
const processedData = {
    deviceId: deviceData.deviceId,
    timestamp: new Date(deviceData.timestamp),
    dataPoints: deviceData.dataPoints.map(point => ({
        pointCode: point.code,
        value: parseFloat(point.value),
        quality: point.quality || 'good',
        processedAt: new Date()
    })),
    metadata: {
        source: 'node-red-processor',
        version: '1.0.0'
    }
};

msg.payload = processedData;
return [msg, null]; // 发送到正常处理流程

// 连接MySQL数据库并插入数据
const mysql = global.get('mysql');
const config = global.get('iotConfig').mysql;

const connection = mysql.createConnection(config);

const deviceData = msg.payload;

// 准备插入语句
const insertQueries = [];

// 插入设备数据点
for (const point of deviceData.dataPoints) {
    const query = `
        INSERT INTO T_DATA_POINTS_HISTORY 
        (F_DeviceId, F_PointCode, F_Value, F_Quality, F_Timestamp, F_ProcessedAt)
        VALUES (?, ?, ?, ?, ?, ?)
    `;
    insertQueries.push({
        sql: query,
        values: [
            deviceData.deviceId,
            point.pointCode,
            point.value.toString(),
            point.quality,
            deviceData.timestamp,
            point.processedAt
        ]
    });
}

// 执行批量插入
Promise.all(insertQueries.map(q => {
    return new Promise((resolve, reject) => {
        connection.query(q.sql, q.values, (err, result) => {
            if (err) reject(err);
            else resolve(result);
        });
    });
})).then(results => {
    connection.end();

    msg.payload = {
        success: true,
        message: `成功插入 ${results.length} 条数据点记录`,
        insertedCount: results.length,
        deviceId: deviceData.deviceId
    };

    node.send([msg, null]);
}).catch(error => {
    connection.end();

    msg.payload = {
        error: '数据库插入失败',
        details: error.message,
        deviceId: deviceData.deviceId
    };

    node.send([null, msg]);
});

// IoT设备规则处理示例
const deviceData = msg.payload;
const deviceId = msg.topic.split('/')[2]; // 从MQTT topic提取设备ID

// 获取设备配置的规则
const mysql = global.get('mysql');
const config = global.get('iotConfig').mysql;

const connection = mysql.createConnection(config);

// 查询设备规则
const ruleQuery = `
    SELECT F_RuleCode, F_RuleName, F_TriggerConditions, F_Actions 
    FROM T_JAVASCRIPT_RULES 
    WHERE F_DeviceId = ? AND F_IsEnabled = 1
`;

connection.query(ruleQuery, [deviceId], (err, rules) => {
    if (err) {
        node.error('查询规则失败: ' + err.message);
        return;
    }

    connection.end();

    // 处理每个规则
    for (const rule of rules) {
        try {
            // 动态执行规则代码
            const ruleFunction = new Function('data', 'deviceId', rule.F_RuleCode);
            const result = ruleFunction(deviceData, deviceId);

            if (result && result.triggered) {
                // 规则触发，发送告警
                const alertMsg = {
                    payload: {
                        alertType: 'rule_triggered',
                        deviceId: deviceId,
                        ruleName: rule.F_RuleName,
                        message: result.message,
                        timestamp: new Date(),
                        data: deviceData
                    }
                };

                node.send([null, alertMsg]); // 发送到告警流程
            }
        } catch (error) {
            node.error(`规则执行失败 [${rule.F_RuleName}]: ${error.message}`);
        }
    }

    // 发送处理后的数据
    msg.payload = {
        ...deviceData,
        deviceId: deviceId,
        processedBy: 'rule-engine',
        rulesApplied: rules.length
    };

    node.send([msg, null]); // 发送到正常数据流
});

// 存储处理后的数据到数据库
const processedData = msg.payload;

node.log(`存储设备数据: ${processedData.deviceId}, 规则数: ${processedData.rulesApplied}`);

// 这里可以添加数据存储逻辑
msg.payload = {
    success: true,
    message: '数据存储成功',
    deviceId: processedData.deviceId
};

return msg;

// 处理设备告警
const alert = msg.payload;

node.warn(`设备告警: ${alert.deviceId} - ${alert.message}`);

// 这里可以添加告警通知逻辑
// 比如发送邮件、短信、推送通知等

msg.payload = {
    alertProcessed: true,
    deviceId: alert.deviceId,
    ruleName: alert.ruleName,
    timestamp: alert.timestamp
};

return msg;
